                class="w-6 h-6 rounded-md flex-shrink-0 mt-0.5"
              />
              <i v-else class="fa-solid fa-folder text-base flex-shrink-0 mt-1"></i>

              <!-- Info -->
              <div class="flex-1 min-w-0">
                <div class="font-medium  transition-colors truncate">
